	INSERT INTO BNTREQTMP 
	(
	    BUYER_ITEM_NO
	    , DESCRIPTION
	    , SPECIFICATION
	    , UNIT_MEASURE
	    , MAKER_NAME
	    , ORIGIN_NAME
	    , BUYER_TARGET_PRICE
	    , ITEM_QTY
	    , AGENT
	    , TMP_REMARK
	    , BUYER
	    , USER_ID
	    , REQ_PRICE_TYPE
	    , BUYER_ASSIGN_AGENT_CODE
	) SELECT 
	    #{BUYER_ITEM_NO}
	    , #{DESCRIPTION}
	    , #{SPECIFICATION}
	    , #{UNIT_MEASURE}
	    , #{MAKER_NAME}
	    , #{ORIGIN_NAME}
	    , #{BUYER_TARGET_PRICE}
	    , #{ITEM_QTY}
	    , #{AGENT}
	    , #{TMP_REMARK}
	    , #{st_buyer}
	    , #{st_user_id}
	    , #{REQ_PRICE_TYPE}
	    , #{BUYER_ASSIGN_AGENT_CODE}
	FROM DUAL


